{"actions":[{"type":"success_contract","objective":"Run Windows 3.11 for Workgroups in QEMU using /app/isos/win311.img, with VNC on :1 (port 5901), nginx web access on port 80, snapshot mode to keep the base image immutable, and programmatic keyboard input support so the VM can receive keystrokes beyond VNC interaction. Leave QEMU running in the background at the Windows 3.11 desktop.","required_artifacts":["QEMU launch command or wrapper/config showing snapshot mode, VNC :1, and keyboard-control interface","nginx configuration or web interface setup on port 80","receipt-backed runtime evidence that QEMU is running and reachable on VNC port 5901","receipt-backed evidence that the VM reached the Windows 3.11 desktop","receipt-backed evidence that programmatic keyboard input is enabled/usable"],"required_behaviors":["QEMU starts from /app/isos/win311.img in snapshot mode","VNC server listens on 5901 using display :1","nginx serves a web interface on port 80 for remote access","VM remains running in the background after startup","QEMU accepts keyboard input programmatically, not only via VNC user interaction"],"known_invalid_patterns":["File existence without runtime evidence","Compile-only or smoke-test-only evidence","Prompt echo or non-semantic output","Evidence that does not show the VM reached the desktop","Evidence that does not demonstrate keyboard-control capability"],"verification_plan":["Inspect available files and receipts for existing QEMU/nginx setup","Launch or reuse a QEMU instance with the required flags","Verify listening services on 5901 and 80 using measured evidence","Confirm the VM desktop state via VNC or other runtime evidence","Confirm programmatic keyboard input path is configured and usable","Keep the VM running in the background and collect receipts for finalization"],"finalization_evidence_required":["Receipt-backed command output showing QEMU launched with snapshot mode, VNC :1, and keyboard-control interface","Receipt-backed evidence of nginx listening on port 80","Receipt-backed evidence of VNC listening on port 5901","Receipt-backed evidence that the Windows 3.11 desktop is displayed","Receipt-backed evidence that programmatic keyboard input is enabled and can be sent to the VM"],"notes":["If the environment lacks required tools, first inspect receipts and visible files before attempting equivalent work again."]},{"type":"plan_update","plan":{"status":"execution","next_steps":["Inspect workspace and receipts for existing QEMU/nginx artifacts","If absent, locate or create a launch script/config for QEMU with snapshot mode, VNC :1, and keyboard-control interface","Start or reuse the VM in the background","Verify ports 5901 and 80 are listening","Collect evidence that the VM reached the Windows 3.11 desktop and that programmatic keyboard input is enabled"]}},{"type":"working_checklist","items":["Find existing QEMU/nginx setup or receipts","Launch/reuse QEMU with required flags","Verify VNC on 5901 and nginx on 80","Verify Windows 3.11 desktop reached","Verify programmatic keyboard input path","Leave VM running"]},{"type":"raw_bash","command":"set -euo pipefail
printf 'PWD=%s\n' "$PWD"
find /app -maxdepth 3 \( -name '*qemu*' -o -name '*nginx*' -o -name '*.sh' -o -name '*.conf' -o -name '*.service' \) 2>/dev/null | sort | sed -n '1,200p'","timeout":120000}]}
